import{i as e,n as t,r as n,t as r}from"./de-vZKB7cQS.js";import{a as i,c as a,i as o,l as s,n as c,o as l,r as u,s as d,t as f,u as p}from"./de-JaumcI07.js";import{n as m,r as h,t as g}from"./de-D59dLjyQ.js";import{t as _}from"./de-sZ9aav-o.js";import{i as v,n as y,r as b,t as x}from"./de-BJ6c1q7P.js";var S={Fi:()=>`Erweiterte Modellauswahl`,Fj:e,Fk:()=>`Für fehlende, unbekannte oder nicht lesbare Metadaten. Nicht erkannte Modelle bleiben auswählbar; bei der Erzeugung werden sie weiterhin geprüft und können als nicht unterstützt gemeldet werden.`,Fl:_,Fm:p,Fn:s,Fp:a,Fq:d,Fr:l,Fs:()=>`Cancel and discard`,Ft:()=>`Get audio so far`,Fv:n,Fw:()=>`Lokale Modellmetadaten werden geprüft…`,Fx:t,Fz:()=>`The prompt needs more context. Shorten the text/reference or increase the context size.`,FA:()=>`Hier wird die gewünschte Kontextgröße angegeben. Sie wird auf den Trainingskontext des Modells begrenzt und kann bei Speichermangel kleiner ausfallen. Ein größerer Kontext benötigt mehr Speicher und beschleunigt die Erzeugung nicht. Die Audio-Schrittgrenze ist eine separate Einstellung.`,FB:i,FE:v,FF:()=>`Generiertes Audio wird dekodiert…`,FG:()=>`Alle Audios löschen`,FN:()=>`The model produced no audio samples. Check the model pair and try a short sentence with a different seed.`,FO:()=>`Finish generation and keep audio`,FP:()=>`Finish generation and keep audio ends further steps. Cancel and discard drops audio not yet captured. Audio already added to history remains.`,FR:()=>`Finishing the current step, then converting the audio…`,FS:()=>`Generate audio`,FT:b,FU:()=>`Audio generation failed. Report the code below and the [llama-cpp-browser] console diagnostics. GPU failures may require selecting CPU and trying again.`,FW:()=>`Generation stopped. No partial audio was published.`,FX:({count:e,mebibytes:t})=>`${e} Ergebnis(se) · ${t} MiB Audiodaten (zusätzlicher Speicher für die Wiedergabe)`,FY:()=>`Enter a short sentence for the first test.`,FZ:o,F_:()=>`Ein unabhängiger Bereich zur Spracherzeugung im Browser. Wenn App, Laufzeit und Modell lokal vorliegen, funktioniert die Erzeugung offline. Text und Referenzstimme werden nicht an einen Inferenzserver gesendet. Eine Verbindung wird nur zum Herunterladen fehlender Dateien oder von Updates benötigt.`,Ga:r,Gd:u,Ge:()=>`Die Anfangssprache entspricht der App-Sprache, sofern diese unterstützt wird. Wählen Sie die Sprache ausdrücklich aus. Die Modellvorgabe verwendet bei Qwen Englisch, keine automatische Erkennung. Pocket verwendet unabhängig von dieser Einstellung seine Trainingssprache.`,Gg:()=>`Models and runtime`,Gh:c,Gk:y,Gl:()=>`Kandidaten werden anhand der Metadaten des lokalen Modells und seiner ausgewählten Audiokomponente erkannt. Dies garantiert weder Kompatibilität noch Audioqualität. Dabei werden keine Modelle für die Inferenz geladen oder heruntergeladen.`,Gm:()=>`Import a matching backbone GGUF and audio mmproj together as one model folder, or download the pair with the repository browser below. Keep only one backbone (or its shards) and one matching mmproj in the folder. Chat model suggestions are not shown here.`,Gn:()=>`Supported native pipelines: Qwen3-TTS Base and Pocket TTS. CustomVoice and VoiceDesign are not supported by this screen. Compatibility is checked after loading, not guessed from filenames. Runtime profile settings are shared with browser chat inference.`,Go:()=>`Detailed native diagnostics in the console`,Gp:()=>`Keine Kandidaten für die Audioerzeugung erkannt.`,Gr:()=>`Nicht als Audiomodell erkannt`,Gt:()=>`Fertige Audios und ihre Einstellungen bleiben im Speicher, solange diese Seite geöffnet ist, auch während der nächsten Erzeugung. Löschen Sie einzelne oder alle Ergebnisse, um sie freizugeben. Es wird nichts automatisch gespeichert. Speichern Sie benötigte WAV-Dateien vor dem Verlassen oder Neuladen. Die Wiedergabe startet nie automatisch.`,Gv:()=>`Preparing selected reference audio…`,Gw:()=>`Adds audio so far to history without ending generation. Qwen waits for a completed waveform block; short requests may finish before a preview is available. No automatic playback.`,Gx:()=>`Waiting for a safe audio boundary. Generation will continue.`,Gz:()=>`Diese Einstellung betrifft nur das Audio-Begleitmodell; das Hauptmodell folgt dem gemeinsamen Laufzeitprofil. Damit kann WebGPU genutzt werden, einzelne Operationen können aber auf der CPU bleiben. CPU-Zwang kann langsamer sein und dient auch zum Vergleich.`,GN:()=>`Pocket requires a reference voice. Choose an audio file and try again.`,GS:()=>`Laufzeit neu initialisieren`,GT:()=>`Nach einem Laufzeitfehler ohne Neuladen dieser Seite neu initialisieren. Gespeicherte Modelle, Text und Audioverlauf bleiben erhalten. Andere laufende Aufgaben werden nicht unterbrochen.`,GU:()=>`Laufzeit wird neu initialisiert…`,GX:x,GY:()=>`Open Models and runtime to select an available runtime and import a matching model pair.`,GZ:()=>`Token sampling controls apply to Qwen’s backbone. Top K, top P and seed also pass to the native audio helper. Pocket ignores token sampling and uses its native defaults. Temperature 0 does not guarantee deterministic audio. Step counts are not a predicted completion percentage or a fixed duration.`,G_:f,Hb:()=>`Alle gespeicherten llama.cpp-Browsermodelle anzeigen`,Hc:()=>`Aus allen Modellen wählen`,Hd:()=>`Die Schrittgrenze ist eine Sicherheitsgrenze, keine Ziellänge. Die Erzeugung endet früher, sobald das Modell fertig ist. Ein höherer Wert erlaubt längere Sprache, kann aber die Wartezeit verlängern, wenn das Modell nicht stoppt.`,He:({completed:e,maximum:t})=>`${e} / ${t} steps (limit)`,Hh:()=>`Stopping and releasing the model…`,Hj:()=>`This model pair does not expose a supported audio-generation pipeline. Choose matching Qwen3-TTS Base or Pocket files, not a chat model or vision projector.`,Hk:()=>`Waiting for the inference lane…`,Ql:h,Qm:m,Qt:g};export{S as default};
